# Regenerates src/data/blogs.ts and src/data/seo.ts and public/sitemap.xml from the SEO/AEO packs.
import re,json,yaml,glob,os
BR="/workspace/rk-blog-rewrites"; SP="/workspace/rk-seo-pages"
posts={"rent-or-buy-construction-equipment":("2026-10-12","/img-33374624.jpg"),"monsoon-site-readiness-checklist":("2026-06-02","/img-31637239.jpg"),"hired-plant-saves-cashflow":("2026-08-18","/img-2137670.jpg"),"14-years-of-showing-up":("2026-09-24","/img-29414416.jpg"),
"construction-equipment-rental-mumbai":("2026-10-31","/site.jpg"),"what-is-rsp-rental":("2026-10-31","/rental.jpg"),"night-pour-plant-hire":("2026-10-31","/img-33511139.jpg"),"yard-checked-equipment-why-it-matters":("2026-10-31","/img-14100101.jpg"),"hire-vs-own-core-rent-peak":("2026-10-31","/sale.jpg")}
def front(p):
    t=open(p).read(); _,fm,body=t.split("---",2); return yaml.safe_load(fm),body.strip()
def faqs_from(txt):
    return [{"q":q.strip(),"a":" ".join(a.split())} for q,a in re.findall(r"^\*\*(.+?\?)\*\*\s*\n(.+?)(?=\n\s*\n|\Z)",txt.strip(),re.S|re.M)]
out=[]
for slug,(date,img) in posts.items():
    m,body=front(f"{BR}/{slug}.md"); assert m["slug"]=="/blog/"+slug
    lines=body.split("\n"); title=lines[0].lstrip("# ").strip(); body="\n".join(lines[1:]).strip()
    sa=re.match(r"\*\*Short answer:\*\*\s*(.+?)\n\n",body,re.S); lead=" ".join(sa.group(1).split()); body=body[sa.end():]
    fm_=re.search(r"^## (FAQs|Frequently asked questions)\s*$",body,re.M)
    rest=body[fm_.end():]; nx=re.search(r"^(## |---\s*$)",rest,re.M)
    faqtxt=rest if not nx else rest[:nx.start()]; after="" if not nx else rest[nx.start():]
    after=re.sub(r"^---\s*$","",after,flags=re.M)
    md=(body[:fm_.start()]+"\n"+after).strip()
    words=len((lead+md+faqtxt).split())
    f=faqs_from(faqtxt); assert len(f)>=3,(slug,len(f))
    out.append(dict(slug=slug,title=title,seoTitle=m["seo_title"],metaDescription=m["meta_description"],primaryQuery=m["primary_query"],date=date,read=f"{max(1,round(words/200))} min",img=img,excerpt=m["meta_description"],lead=lead,body=md,faqs=f))
    print(slug,len(f))
open("src/data/blogs.ts","w").write('export type Faq = { q: string; a: string };\nexport type Blog = { slug: string; title: string; seoTitle: string; metaDescription: string; primaryQuery: string; date: string; read: string; img: string; excerpt: string; lead: string; body: string; faqs: Faq[] };\n// Generated by scripts_gen_content.py from /workspace/rk-blog-rewrites/*.md\nexport const BLOGS: Blog[] = '+json.dumps(out,indent=1,ensure_ascii=False)+";\n")
def pack(p):
    m,body=front(p)
    return dict(path=m["path"],seoTitle=m["seo_title"],metaDescription=m["meta_description"],h1=m.get("h1",""),lead=m.get("lead",""),faqs=[{"q":x["q"],"a":x["a"]} for x in m.get("faqs",[])],body=body)
pages={}
for n in ["home","about","services","rsp-rental","rsp-sale","projects-index","contact","blog-index"]:
    pages[n]=pack(f"{SP}/{n}.md")
pages["projects-index"]["body"]="Every card is a real client and a real site. Where a location wasn't recorded, we say so rather than guess."
pages["blog-index"]["body"]=""
proj={os.path.basename(p)[:-3]:pack(p) for p in glob.glob(f"{SP}/projects/*.md") if not p.endswith("_template-notes.md")}
print(len(proj),"project packs")
open("src/data/seo.ts","w").write('export type SeoFaq = { q: string; a: string };\nexport type SeoPage = { path: string; seoTitle: string; metaDescription: string; h1: string; lead: string; faqs: SeoFaq[]; body: string };\n// Generated by scripts_gen_content.py from /workspace/rk-seo-pages\nexport const PAGES: Record<string, SeoPage> = '+json.dumps(pages,indent=1,ensure_ascii=False)+';\nexport const PROJECT_SEO: Record<string, SeoPage> = '+json.dumps(proj,indent=1,ensure_ascii=False)+";\n")
slugs=re.findall(r'"slug": "([^"]+)"',open("src/data/projects.ts").read())
base="https://rk-enterprises.dhajare94.workers.dev"
urls=["/","/about","/services","/services/rsp-rental","/services/rsp-sale","/projects","/contact","/blog"]+[f"/blog/{s}" for s in posts]+[f"/projects/{s}" for s in slugs]
open("public/sitemap.xml","w").write('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+"".join(f"  <url><loc>{base}{u}</loc><lastmod>2026-10-31</lastmod></url>\n" for u in urls)+"</urlset>\n")
print(len(urls),"urls")
